import addressBook from "./addresses.json";

export * from "./abis";

/** Chain ids WattSwap supports. */
export const CHAIN_IDS = { anvil: 31337, sepolia: 11155111 } as const;

export type ChainKey = keyof typeof CHAIN_IDS;

export type ContractName =
  "EnergyToken" | "MockUSDC" | "WattSwapExchange" | "MeterRegistry" | "PriceOracle";

export type Address = `0x${string}`;

/** Deployed contract addresses for one chain. Empty until that chain has been deployed. */
export type AddressBook = Partial<Record<ContractName, Address>>;

/** Generated by `make export-abis` from the Foundry broadcast files. */
export const ADDRESSES: Record<ChainKey, AddressBook> = addressBook as Record<
  ChainKey,
  AddressBook
>;

/** EIP-712 market id used by v1: keccak256("WATT-mUSDC"). */
export const WATT_MUSDC_MARKET_ID: Address =
  "0x3091fb835c35931db16c8b4491333c0472dfb50cef1d2f41dab8f471c8924507";

export function chainIdFor(key: ChainKey): number {
  return CHAIN_IDS[key];
}

/** Returns the address of a contract on a chain, or throws if it was not deployed there. */
export function addressOf(chain: ChainKey, name: ContractName): Address {
  const address = ADDRESSES[chain][name];
  if (address === undefined) {
    throw new Error(`${name} is not deployed on ${chain}`);
  }
  return address;
}
